package com.jobsphere.service;
import com.jobsphere.entity.User; import com.jobsphere.repository.UserRepository; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AuthService { private final UserRepository repo; private final BCryptPasswordEncoder enc=new BCryptPasswordEncoder(); public AuthService(UserRepository r){repo=r;} public User create(String name,String email,String password){User u=new User();u.fullName=name.trim();u.email=email.trim().toLowerCase(Locale.ROOT);u.passwordHash=enc.encode(password);u.role=User.Role.USER;u.active=true;u.createdAt=java.time.LocalDateTime.now();return repo.save(u);} public boolean matches(String raw,String hash){return enc.matches(raw,hash);} }
